WITH remaining_keys AS (SELECT id, event_type FROM web_events INTERSECT ALL SELECT id, event_type FROM web_events WHERE event_type IN ('search', 'add_to_cart')), verified AS (SELECT s.* FROM web_events s INNER JOIN remaining_keys k ON s.id = k.id AND s.event_type = k.event_type) SELECT session_id, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) AS cnt, COUNT_IF(page = '/search') AS search_events, AVG(duration_sec) FILTER (WHERE event_type = 'page_view') AS page_view_avg_duration_sec, APPROX_PERCENTILE(duration_sec, ARRAY(0.25, 0.5, 0.75)) AS duration_sec_quartiles FROM verified GROUP BY 1;
